    var tipStyle = getComputedStyle(tip);
    var fontSize = parseFloat(tipStyle && tipStyle.getPropertyValue && tipStyle.getPropertyValue("--ui-font-size")) || 14;
    var scale = Math.max(0.8, Math.min(1, 14 / fontSize));
